fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let rowh: i32 = 26;
    let scroll: i32 = t / 3;
    let pal = [0x9c4a3c, 0xb05a48, 0x8a4034, 0xa85242];
    host::display::clear(0x2a2a2e);
    let mut rr: i32 = 0;
    while rr < h / rowh + 2 {
        let wr: i32 = rr + scroll / rowh;
        let y: i32 = rr * rowh - scroll % rowh;
        let off: i32 = if (wr & 1) == 1 { 0 - 30 } else { 0 };
        let mut x: i32 = off;
        let mut b: i32 = 0;
        while x < w {
            let mut hsh: i32 = wr * 7919 + b * 104729;
            hsh = hsh * 1103515245 + 12345;
            let bw: i32 = 34 + ((hsh >> 16) & 63);
            host::display::fill_rect(x, y, bw - 3, rowh - 4, pal[(hsh >> 8) & 3]);
            x = x + bw;
            b = b + 1;
        }
        rr = rr + 1;
    }
    host::display::present();
}
